import{_ as e,o,c as i,a as n}from"./app-eae545e9.js";const r={},d=n('<h1 id="命令模式-command-pattern" tabindex="-1"><a class="header-anchor" href="#命令模式-command-pattern" aria-hidden="true">#</a> 命令模式（Command Pattern）</h1><h2 id="示例" tabindex="-1"><a class="header-anchor" href="#示例" aria-hidden="true">#</a> 示例</h2><p>用户通过遥控器控制空调、风扇、电灯等设备，只需按下按钮即可触发开/关等操作，而无需关心设备内部复杂的电路或执行逻辑。</p><h2 id="设计思想" tabindex="-1"><a class="header-anchor" href="#设计思想" aria-hidden="true">#</a> 设计思想</h2><p>将“请求”封装成独立的命令对象，使请求发起方（Invoker，如遥控器）与请求接收方（Receiver，如电视、电灯）解耦。Invoker 只需调用命令对象的 <code>execute()</code>，具体由哪个 Receiver 执行、如何执行，都封装在 ConcreteCommand 中。</p><h2 id="核心角色" tabindex="-1"><a class="header-anchor" href="#核心角色" aria-hidden="true">#</a> 核心角色</h2><ul><li><strong>Command</strong>：命令接口，声明 <code>execute()</code>（以及可选的 <code>undo()</code>）；</li><li><strong>ConcreteCommand</strong>：具体命令，持有 Receiver 引用，负责将请求委托给 Receiver；</li><li><strong>Receiver</strong>：真正执行操作的对象；</li><li><strong>Invoker</strong>：调用者，持有并触发命令；</li><li><strong>Client</strong>：创建 Receiver 和 ConcreteCommand，并将它们装配到 Invoker。</li></ul><h2 id="在-jdk-和-spring-中的应用" tabindex="-1"><a class="header-anchor" href="#在-jdk-和-spring-中的应用" aria-hidden="true">#</a> 在 JDK 和 Spring 中的应用</h2><ul><li><p><strong>JDK</strong></p><ul><li><code>Runnable</code> / <code>Callable</code> 相当于 ConcreteCommand；</li><li><code>Thread</code>、<code>Executor</code>、<code>ExecutorService</code> 相当于 Invoker；</li><li>Swing 中的 <code>ActionListener</code>、<code>javax.swing.undo.UndoableEdit</code> 也是典型应用。</li></ul></li><li><p><strong>Spring</strong></p><ul><li><code>CommandLineRunner</code> / <code>ApplicationRunner</code>：Spring Boot 启动时由容器统一执行；</li><li><code>TaskExecutor</code>：将任务提交与执行解耦；</li><li>Spring MVC 的 <code>DispatcherServlet</code> + <code>HandlerAdapter</code>：请求分发器作为 Invoker，Controller 作为具体命令；</li><li>Spring Integration 的 <code>MessageHandler</code>、Spring State Machine 的 <code>Action</code> 等。</li></ul></li></ul><h2 id="使用总结" tabindex="-1"><a class="header-anchor" href="#使用总结" aria-hidden="true">#</a> 使用总结</h2><ol><li><p><strong>优点</strong></p><ul><li>请求被封装为对象，调用者与执行者完全解耦；</li><li>天然支持 <code>undo</code> / <code>redo</code>，也便于实现命令队列、日志记录、事务回滚、宏命令等；</li><li>新增 Receiver 或命令时，只需扩展具体类，符合开闭原则。</li></ul></li><li><p><strong>注意事项</strong></p><ul><li>命令类过多时可能造成“类爆炸”，可通过参数化命令、函数式接口、通用命令类或宏命令来缓解；</li><li>如果每个命令都很简单，直接方法调用即可，不必强行使用命令模式，避免过度设计。</li></ul></li></ol>',11),c=[d];function a(l,t){return o(),i("div",null,c)}const h=e(r,[["render",a],["__file","minglingmoshi.html.vue"]]);export{h as default};
